// GSPack: Crux blocks for the Allthemodium seeds (config/mysticalcustomization/crops).
// A crop only grows when its Crux is placed directly under the farmland.
// Textures live in kubejs/assets/gspack/textures/block/<id>.png (generated by tools/make-item-textures.ps1).

const GSPACK_CRUX_BLOCKS = [
  // id, display name
  ['allthemodium_crux', 'Allthemodium Crux'],
  ['vibranium_crux', 'Vibranium Crux'],
  ['unobtainium_crux', 'Unobtainium Crux']
]

StartupEvents.registry('block', event => {
  GSPACK_CRUX_BLOCKS.forEach(([id, name]) => {
    event.create(`gspack:${id}`)
      .displayName(name)
      .soundType('metal')
      .hardness(5)
      .resistance(1200)
      .requiresTool(true)
      .tagBlock('minecraft:mineable/pickaxe')
      .texture(`gspack:block/${id}`)
  })
})
